"""Validation rules migrated from Meridian CRM 4.2 account_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(record: dict | None, field: str) -> Any:
    """Return a field value, treating missing or None values as empty strings."""
    if record is None:
        return ""
    value = record.get(field, "")
    return "" if value is None else value


def _length(value: Any) -> int:
    """Implement legacy LEN semantics."""
    if value is None:
        return 0
    return len(str(value))


def _number(value: Any) -> Decimal:
    """Coerce a NUMBER value according to legacy numeric-context semantics."""
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate the migrated ACCT_MASTER rules in legacy rule-file order."""
    del today  # Part of the fixed interface; unused by these rules.

    errors: list[dict] = []

    # ACC-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "ACCT_NM")) < 2:
            errors.append(
                _failure("E1001", "Account name too short")
            )

    # ACC-002: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _value(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            errors.append(
                _failure("E1002", "Invalid account type")
            )

    # ACC-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        annual_revenue = _value(record, "ANN_REV")
        if annual_revenue == "":
            annual_revenue = 0
        if _number(annual_revenue) < 0:
            errors.append(
                _failure("E1003", "Annual revenue negative")
            )

    # ACC-004: UPDATE only
    if event == "UPDATE":
        releases_hold = (
            _value(old, "CRED_HOLD") == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= 0
        )
        if releases_hold:
            errors.append(
                _failure(
                    "E1004",
                    "Cannot release credit hold with zero credit limit",
                )
            )

    # ACC-005: INSERT, UPDATE; warning severity
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "REGION_CD")) != 3:
            errors.append(
                _failure(
                    "E1005",
                    "Region code must be 3 chars",
                    "WARN",
                )
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return True when at least one validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
